<?php require_once 'tx_lib.php';require_login();$pdo=db();
$year=(int)($_GET['year']??date('Y'));$month=max(1,min(12,(int)($_GET['month']??date('n'))));$account=(int)($_GET['account']??0);
ensure_year($year);
$allAccounts=$pdo->query('SELECT id,name,active FROM accounts ORDER BY id')->fetchAll();
$accounts=array_values(array_filter($allAccounts,fn($a)=>(int)$a['active']===1));
$accs=$account?array_values(array_filter($allAccounts,fn($a)=>(int)$a['id']===$account)):$accounts;
$settings=settings_all();
$start=sprintf('%04d-%02d-01',$year,$month);$end=date('Y-m-d',strtotime($start.' +1 month'));
$mx=month_matrix($year,$account); // 1 requête groupée pour toute l'année
$monthLabel=month_fr($month);
// Inventaire du mois et situation annuelle : calculés en mémoire à partir de la matrice annuelle.
$monthly=[];$annual=[];
foreach($accs as $a){$id=(int)$a['id'];foreach(['USD','FC'] as $cur){
  $b=balance_for($id,$year,$cur);$prior=0.0;
  for($m=1;$m<$month;$m++)$prior+=($mx[$id][$cur][$m]['income']??0.0)-($mx[$id][$cur][$m]['expense']??0.0);
  $mo=$b['opening_amount']+$prior;$inc=$mx[$id][$cur][$month]['income']??0.0;$exp=$mx[$id][$cur][$month]['expense']??0.0;
  $monthly[]=['account_name'=>$a['name'],'account_id'=>$id,'currency'=>$cur,'opening'=>$mo,'income'=>$inc,'expense'=>$exp,'closing'=>$mo+$inc-$exp];
  $annual[]=['account_name'=>$a['name'],'account_id'=>$id,'currency'=>$cur]+$b;
}}
$cq=$pdo->prepare('SELECT mi.*,a.name account_name,u.full_name closer FROM monthly_inventories mi JOIN accounts a ON a.id=mi.account_id LEFT JOIN users u ON u.id=mi.closed_by WHERE mi.year=? AND mi.month=?'.($account?' AND mi.account_id=?':'').' ORDER BY a.name,mi.currency');$cp=[$year,$month];if($account)$cp[]=$account;$cq->execute($cp);$closures=$cq->fetchAll();
// Offrandes spéciales : le solde cumulé du mois part du solde réel au début du mois (solde initial + mois précédents).
$specialId=0;foreach($allAccounts as $a)if($a['name']==='Offrandes spéciales'){$specialId=(int)$a['id'];break;}
$specialRows=[];$specialStart=[];
if($specialId){
  $special=$pdo->prepare("SELECT t.tx_date,t.type,t.currency,t.amount,t.label,u.full_name creator FROM transactions t LEFT JOIN users u ON u.id=t.created_by WHERE t.account_id=? AND t.tx_date>=? AND t.tx_date<? ORDER BY t.tx_date,t.id");$special->execute([$specialId,$start,$end]);$specialRows=$special->fetchAll();
  if($specialRows){$smx=month_matrix($year,$specialId);foreach(['USD','FC'] as $cur){$p=balance_for($specialId,$year,$cur)['opening_amount'];for($m=1;$m<$month;$m++)$p+=($smx[$specialId][$cur][$m]['income']??0.0)-($smx[$specialId][$cur][$m]['expense']??0.0);$specialStart[$cur]=$p;}}
}
// Dépenses classées par la catégorie ENREGISTRÉE avec chaque opération (catégorie choisie, sinon le libellé lui-même) :
// un libellé nouveau devient sa propre catégorie, il n'y a plus de ligne « Autres » fourre-tout.
$categoryTotals=[];$categoryAnnual=[];
$ce=tx_cat_expr('t','c');
$st=$pdo->prepare("SELECT $ce cat,t.currency,MONTH(t.tx_date) m,SUM(t.amount) s FROM transactions t LEFT JOIN categories c ON c.id=t.category_id WHERE t.type='expense' AND t.tx_date>=? AND t.tx_date<?".($account?' AND t.account_id=?':'')." GROUP BY $ce,t.currency,MONTH(t.tx_date)");$args=[sprintf('%04d-01-01',$year),sprintf('%04d-01-01',$year+1)];if($account)$args[]=$account;$st->execute($args);
$catShown=[]; // clé normalisée (casse/espaces ignorés) => nom affiché
foreach($st->fetchAll() as $x){$nm=trim((string)$x['cat']);if($nm==='')$nm='(sans catégorie)';$nk=norm_key($nm);$catName=$catShown[$nk]??($catShown[$nk]=$nm);$key=$catName.'|'.$x['currency'];$categoryAnnual[$key]=($categoryAnnual[$key]??0)+(float)$x['s'];if((int)$x['m']===$month)$categoryTotals[$key]=($categoryTotals[$key]??0)+(float)$x['s'];}
ksort($categoryTotals);ksort($categoryAnnual);
// Totaux du mois par compte, type et devise (depuis la même matrice).
$scope=$account?$accs:$allAccounts;usort($scope,fn($a,$b)=>strcmp($a['name'],$b['name']));
$typeTotals=[];$allTotals=['income'=>['USD'=>0.0,'FC'=>0.0],'expense'=>['USD'=>0.0,'FC'=>0.0]];
foreach($scope as $a)foreach(['expense','income'] as $t)foreach(['FC','USD'] as $cur){$v=$mx[(int)$a['id']][$cur][$month][$t]??null;if($v===null)continue;$typeTotals[]=['account_name'=>$a['name'],'type'=>$t,'currency'=>$cur,'total'=>$v];$allTotals[$t][$cur]+=$v;}
$page_title='Rapports et inventaires';include 'partials/header.php';?>
<div class="panel no-print"><div class="panel-head"><div><h2>Filtres des rapports</h2><p>Inventaire mensuel, trimestriel ou annuel par compte.</p></div><button class="btn primary" data-preview="#printArea">Aperçu et impression (zoom)</button></div><form class="filter-row"><select name="account"><option value="0">Tous les comptes</option><?php foreach($accounts as $a):?><option value="<?=$a['id']?>" <?=$account===(int)$a['id']?'selected':''?>><?=h($a['name'])?></option><?php endforeach?></select><select name="year"><?php for($y=(int)date('Y')+1;$y>=(int)date('Y')-10;$y--):?><option value="<?=$y?>" <?=$year===$y?'selected':''?>><?=$y?></option><?php endfor?></select><select name="month"><?php for($m=1;$m<=12;$m++):?><option value="<?=$m?>" <?=$month===$m?'selected':''?>><?=h(ucfirst(month_fr($m)))?></option><?php endfor?></select><button class="btn">Afficher</button></form><a href="export.php?from=<?=$year?>-01-01&to=<?=$year?>-12-31">Exporter les opérations de l'année en Excel (CSV)</a> · <a href="offrandes.php?account=<?=$account?>&year=<?=$year?>&month=<?=$month?>">Sommes par libellé et par mois →</a> · <a href="rapport_periodique.php?scope=month&mois=<?=sprintf('%04d-%02d',$year,$month)?>&account=<?=$account?>">Entrées / sorties par jour, semaine, mois →</a> · <a href="categories_rapport.php?scope=month&mois=<?=sprintf('%04d-%02d',$year,$month)?>&account=<?=$account?>">Rapport par catégorie →</a></div>
<div id="printArea"><div class="report-head"><?php if(!empty($settings['logo_path'])):?><img src="<?=h($settings['logo_path'])?>" alt="Logo" style="max-width:90px;max-height:70px;object-fit:contain"><?php else:?><div class="brand-mark" style="margin:auto">EGD</div><?php endif?><h1><?=h($settings['church_name']??'EGLISE GERME DE DAVID')?></h1><p><?=h($settings['report_description']??'Rapport financier')?> · <?=h($year)?></p><small>Inventaire mensuel : <?=h($monthLabel)?> <?=h($year)?></small></div>

<div class="panel"><h2>Somme de toutes les opérations par compte et par type — <?=h($monthLabel)?> <?=h($year)?></h2><p>Toutes les recettes et dépenses enregistrées pour le mois, avec les devises conservées séparément.</p><div class="table-wrap"><table><thead><tr><th>Compte</th><th>Type</th><th>Devise</th><th>Somme</th></tr></thead><tbody><?php foreach($typeTotals as $tt):?><tr><td><?=h($tt['account_name'])?></td><td><?=h($tt['type']==='income'?'Recettes':'Dépenses')?></td><td><?=h($tt['currency'])?></td><td class="num"><?=money($tt['total'],$tt['currency'])?></td></tr><?php endforeach?><tr><th colspan="2">Total recettes</th><th>USD</th><th class="num"><?=money($allTotals['income']['USD'],'USD')?></th></tr><tr><th colspan="2">Total recettes</th><th>FC</th><th class="num"><?=money($allTotals['income']['FC'],'FC')?></th></tr><tr><th colspan="2">Total dépenses</th><th>USD</th><th class="num"><?=money($allTotals['expense']['USD'],'USD')?></th></tr><tr><th colspan="2">Total dépenses</th><th>FC</th><th class="num"><?=money($allTotals['expense']['FC'],'FC')?></th></tr></tbody></table></div></div>
<div class="panel"><h2>Somme des dépenses mensuelles — <?=h($monthLabel)?> <?=h($year)?></h2><p>Chaque dépense est classée dans sa catégorie enregistrée. Un libellé nouveau devient automatiquement une catégorie : le rapport reste explicite, sans ligne « Autres » fourre-tout.</p><div class="table-wrap"><table><tr><th>Catégorie</th><th>USD</th><th>FC</th></tr><?php $names=[];foreach($categoryTotals as $k=>$v){$names[explode('|',$k)[0]]=true;}foreach(array_keys($names) as $n):?><tr><td><?=h($n)?></td><td class="num"><?=money($categoryTotals[$n.'|USD']??0,'USD')?></td><td class="num"><?=money($categoryTotals[$n.'|FC']??0,'FC')?></td></tr><?php endforeach?><tr><th>Total dépenses</th><th class="num"><?=money(array_sum(array_filter($categoryTotals,fn($k)=>str_ends_with($k,'|USD'),ARRAY_FILTER_USE_KEY)),'USD')?></th><th class="num"><?=money(array_sum(array_filter($categoryTotals,fn($k)=>str_ends_with($k,'|FC'),ARRAY_FILTER_USE_KEY)),'FC')?></th></tr></table></div></div>
<div class="panel"><h2>Somme annuelle par catégorie — <?=h($year)?></h2><div class="table-wrap"><table><tr><th>Catégorie</th><th>USD</th><th>FC</th></tr><?php $names=[];foreach($categoryAnnual as $k=>$v){$names[explode('|',$k)[0]]=true;}foreach(array_keys($names) as $n):?><tr><td><?=h($n)?></td><td class="num"><?=money($categoryAnnual[$n.'|USD']??0,'USD')?></td><td class="num"><?=money($categoryAnnual[$n.'|FC']??0,'FC')?></td></tr><?php endforeach?></table></div></div>
<div class="panel"><h2>Offrandes ordinaires — modèle mensuel <?=h($year)?></h2><div class="table-wrap"><table><thead><tr><th>Mois</th><th>Devise</th><th>Solde initial</th><th>Entrée</th><th>Sortie</th><th>Solde</th><th>Solde cumulé</th></tr></thead><tbody><?php foreach($accs as $a):if($a['name']!=='Offrandes ordinaires')continue;$id=(int)$a['id'];foreach(['FC','USD'] as $cur):$op=balance_for($id,$year,$cur)['opening_amount'];for($m=1;$m<=12;$m++):$i=$mx[$id][$cur][$m]['income']??0.0;$e=$mx[$id][$cur][$m]['expense']??0.0;?><tr><td><?=h(ucfirst(month_fr($m)))?></td><td><?=$cur?></td><td class="num"><?=money($op,$cur)?></td><td class="num"><?=money($i,$cur)?></td><td class="num"><?=money($e,$cur)?></td><td class="num"><?=money($i-$e,$cur)?></td><td class="num"><?=money($op+$i-$e,$cur)?></td></tr><?php $op+=$i-$e;endfor;endforeach;endforeach?></tbody></table></div></div>
<div class="panel"><h2>Inventaire détaillé de chaque compte — <?=h($monthLabel)?></h2><div class="table-wrap"><table><thead><tr><th>Compte</th><th>Devise</th><th>Solde initial</th><th>Entrées</th><th>Sorties</th><th>Solde de clôture théorique</th></tr></thead><tbody><?php foreach($monthly as $r):?><tr><td><?=h($r['account_name'])?></td><td><?=$r['currency']?></td><td class="num"><?=money($r['opening'],$r['currency'])?></td><td class="num"><?=money($r['income'],$r['currency'])?></td><td class="num"><?=money($r['expense'],$r['currency'])?></td><td class="num"><?=money($r['closing'],$r['currency'])?></td></tr><?php endforeach?></tbody></table></div></div>
<div class="panel"><h2>Offrandes spéciales — détail des mouvements</h2><p>Colonnes de suivi conformes au modèle fourni : date, entrée, sortie, libellé, solde et solde cumulé. Les devises sont maintenues distinctes.</p><div class="table-wrap"><table><tr><th>Date</th><th>Entrée</th><th>Sortie</th><th>Libellé</th><th>Devise</th><th>Solde cumulé</th><th>Enregistré par</th></tr><?php $specialBalances=$specialStart;foreach($specialRows as $r):$cur=$r['currency'];$specialBalances[$cur]+=$r['type']==='income'?(float)$r['amount']:-((float)$r['amount']);?><tr><td><?=date('d/m/Y',strtotime($r['tx_date']))?></td><td><?=h($r['type']==='income'?money($r['amount'],$r['currency']):'—')?></td><td><?=h($r['type']==='expense'?money($r['amount'],$r['currency']):'—')?></td><td><?=h($r['label'])?></td><td><?=$r['currency']?></td><td class="num"><?=money($specialBalances[$cur],$cur)?></td><td><?=h($r['creator']??'—')?></td></tr><?php endforeach?></table></div></div>
<div class="panel"><h2>Clôtures enregistrées pour le mois</h2><div class="table-wrap"><table><tr><th>Compte</th><th>Devise</th><th>Solde de clôture</th><th>Clôturé par</th><th>Date de clôture</th></tr><?php foreach($closures as $cl):?><tr><td><?=h($cl['account_name'])?></td><td><?=$cl['currency']?></td><td class="num"><?=money($cl['closing_amount'],$cl['currency'])?></td><td><?=h($cl['closer']??'—')?></td><td><?=h($cl['closed_at'])?></td></tr><?php endforeach?><?php if(!$closures):?><tr><td colspan="5">Aucune clôture enregistrée pour ce mois.</td></tr><?php endif?></table></div></div><div class="panel"><h2>Situation annuelle — <?=h($year)?></h2><div class="table-wrap"><table><tr><th>Compte</th><th>Devise</th><th>Solde initial</th><th>Entrées année</th><th>Sorties année</th><th>Solde final</th></tr><?php foreach($annual as $r):?><tr><td><?=h($r['account_name'])?></td><td><?=$r['currency']?></td><td class="num"><?=money($r['opening_amount'],$r['currency'])?></td><td class="num"><?=money($r['income'],$r['currency'])?></td><td class="num"><?=money($r['expense'],$r['currency'])?></td><td class="num"><?=money($r['balance'],$r['currency'])?></td></tr><?php endforeach?></table></div></div>
</div><?php if(in_array(role(),['admin','treasurer'],true)):?><div class="panel no-print"><h2>Clôture / inventaire mensuel</h2><p>Une clôture verrouille le mois (plus de saisie, de modification ni de suppression) et ne peut être enregistrée qu'une fois pour chaque compte et devise. Un administrateur peut la rouvrir ou la réinitialiser plus bas si une correction est nécessaire.</p><form method="post" action="close_month.php" class="filter-row"><?=csrf_field()?><input type="hidden" name="year" value="<?=$year?>"><input type="hidden" name="month" value="<?=$month?>"><select name="account_id"><option value="0">Tous les comptes</option><?php foreach($accounts as $a):?><option value="<?=$a['id']?>"><?=h($a['name'])?></option><?php endforeach?></select><button class="btn primary" onclick="return confirm('Confirmer la clôture de ce mois ?')">Effectuer la clôture</button></form></div><?php endif?>
<?php if(role()==='admin'):
$cm=$pdo->prepare('SELECT DISTINCT month FROM monthly_inventories WHERE year=? ORDER BY month');$cm->execute([$year]);$closedMonths=array_map('intval',$cm->fetchAll(PDO::FETCH_COLUMN));?>
<div class="panel no-print"><h2>Rouvrir ou réinitialiser un mois clôturé</h2>
<p>Mois clôturés en <?=h($year)?> : <?php if($closedMonths):foreach($closedMonths as $i=>$cmm):?><a href="reports.php?year=<?=$year?>&amp;month=<?=$cmm?>&amp;account=<?=$account?>"><?=h(month_fr($cmm))?></a><?=$i<count($closedMonths)-1?', ':''?><?php endforeach;else:?>aucun<?php endif?>.</p>
<p><b>Rouvrir</b> : déverrouille <?=h($monthLabel)?> <?=h($year)?> (la saisie, la modification et la suppression redeviennent possibles ; aucune opération n'est touchée). <b>Réinitialiser</b> : rouvre puis refait aussitôt la clôture avec les chiffres actuels. L'ancienne clôture est conservée dans le journal d'audit.</p>
<form method="post" action="reopen_month.php" class="filter-row"><?=csrf_field()?><input type="hidden" name="year" value="<?=$year?>"><input type="hidden" name="month" value="<?=$month?>"><select name="account_id"><option value="0">Tous les comptes</option><?php foreach($accounts as $a):?><option value="<?=$a['id']?>" <?=$account===(int)$a['id']?'selected':''?>><?=h($a['name'])?></option><?php endforeach?></select><select name="mode"><option value="reopen">Rouvrir le mois (déverrouiller)</option><option value="recalc">Réinitialiser (rouvrir puis reclôturer)</option></select><button class="btn" onclick="return confirm('Appliquer à <?=h($monthLabel)?> <?=h($year)?> ?')">Appliquer</button></form></div>
<?php endif?>
<?php include 'partials/footer.php';?>
